// Evaluate signals against thresholds
const thresholds = $('Set Thresholds').item.json;
const response = $input.item.json;
const records = response.records || [];

const signals = records.map(r => r.fields);

let shouldTriggerAnalysis = false;
const breaches = [];

for (const signal of signals) {
  const { signal_type, delta_pct } = signal;

  if (signal_type === 'support_contacts' && delta_pct > thresholds.support_contacts_threshold) {
    shouldTriggerAnalysis = true;
    breaches.push(`support_contacts: +${delta_pct}% (threshold: +${thresholds.support_contacts_threshold}%)`);
  }
  if (signal_type === 'error_rate' && delta_pct > thresholds.error_rate_threshold) {
    shouldTriggerAnalysis = true;
    breaches.push(`error_rate: +${delta_pct}% (threshold: +${thresholds.error_rate_threshold}%)`);
  }
  if (signal_type === 'completion_rate' && delta_pct < thresholds.completion_rate_threshold) {
    shouldTriggerAnalysis = true;
    breaches.push(`completion_rate: ${delta_pct}% (threshold: ${thresholds.completion_rate_threshold}%)`);
  }
  if (signal_type === 'app_review' && signal.value > thresholds.app_review_threshold) {
    shouldTriggerAnalysis = true;
    breaches.push(`app_review: ${signal.value} mentions (threshold: ${thresholds.app_review_threshold})`);
  }
}

console.log(`Signal check for ${thresholds.deployment_id}: shouldTrigger=${shouldTriggerAnalysis}`);
if (breaches.length > 0) console.log('Breaches:', breaches.join(', '));

return [{
  json: {
    shouldTriggerAnalysis,
    breaches,
    deployment_id: thresholds.deployment_id,
    signal_count: signals.length
  }
}];

// Log that no threshold was breached this cycle
console.log('Signal check complete — no threshold breached. Monitoring continues.');
return [{ json: { status: 'monitoring', message: 'No threshold breached this cycle' } }];
